    ['бескраиний','бескрайний','перед глухим к пишется с'],['бесопасный','безопасный','перед гласным о пишется з'],['бесвредный','безвредный','перед звонким в пишется з'],['безполезный','бесполезный','перед глухим п пишется с'],['безшумный','бесшумный','перед глухим ш пишется с'],['изпугаться','испугаться','перед глухим п пишется с'],['испугать (вариант: изпугать)','испугать','перед глухим п пишется с'],['разписать','расписать','перед глухим п пишется с'],['расбудить','разбудить','перед звонким б пишется з'],['разкрасить','раскрасить','перед глухим к пишется с'],['расжечь','разжечь','перед звонким ж пишется з'],['изчезнуть','исчезнуть','перед глухим ч пишется с'],['исдать','издать','перед звонким д пишется з'],['возпеть','воспеть','перед глухим п пишется с'],['рассвет','рассвет','перед глухим с пишется с'],['рассказать','рассказать','перед глухим с пишется с'],['разговор','разговор','перед звонким г пишется з'],['бесконечный','бесконечный','перед глухим к пишется с'],['бездомный','бездомный','перед звонким д пишется з'],['разбудить','разбудить','перед звонким б пишется з']
